batchroot=pathlib.Path("tools/core20k_sense_v1/release/v21-missing-batch500-all")
entries=json.loads(r'''{"outskirts":["市郊；外围地区","They bought a house on the ___ of town.","市郊"],"plateful":["满满一盘的量","He served himself a ___ of rice.","满满一盘"],"barmaid":["酒吧女服务员（传统称呼）","The ___ served drinks at the old pub.","酒吧服务员"],"abstention":["戒除；克制","The doctor recommended ___ from alcohol.","戒酒"],"regal":["帝王般的；威严的","The queen entered with a ___ bearing.","威严的"],"stupidly":["愚蠢地","He ___ forgot to save the document.","愚蠢地"],"coda":["乐曲尾声","The composer added a brief ___ to the movement.","乐曲尾声"],"cantata":["康塔塔；清唱套曲","The choir performed a Bach ___ on Sunday.","清唱套曲"],"haughty":["傲慢的","His ___ manner offended the guests.","傲慢的"],"censer":["香炉","The priest carried a ___ during the procession.","香炉"],"empress":["女皇；皇后","The ___ ruled the empire for many years.","女皇"],"brigadier":["准将","The ___ inspected the military camp.","准将"],"bewilderment":["困惑；茫然","She stared at the complex map in ___.","困惑"],"firelight":["火光","We read stories by the soft ___.","火光"],"mutton":["成年羊肉","The chef prepared a stew of ___ and vegetables.","羊肉"],"fervently":["热烈地；诚挚地","The volunteers ___ supported the proposal.","热烈地"],"dexterity":["手部灵巧度","The surgeon's skill required exceptional ___.","手部灵巧"],"outhouse":["户外厕所","The old farmhouse still had an ___.","户外厕所"],"courtly":["彬彬有礼的；宫廷式的","He greeted the ambassador with ___ manners.","宫廷式的"],"oratory":["演讲术；雄辩","The candidate's ___ impressed the crowd.","演讲技巧"],"nightfall":["黄昏；入夜时分","We returned to camp before ___.","夜幕降临"],"irate":["愤怒的","An ___ customer demanded a refund.","愤怒的"],"scornfully":["轻蔑地","She ___ dismissed the suggestion.","轻蔑地"],"whimsical":["异想天开的；随心所欲的","The designer chose a ___ shape for the fountain.","异想天开的"],"duodenum":["十二指肠","Food passes from the stomach into the ___.","十二指肠"],"bearable":["可以忍受的","The cool breeze made the heat ___.","可以忍受的"],"paleontologist":["古生物学家","A ___ examined the fossilized bones.","古生物学家"],"clubroom":["俱乐部活动室","Members gathered in the ___ after practice.","活动室"],"obsidian":["黑曜石","The ancient tool was made from ___.","黑曜石"],"nonhuman":["非人类的","The study examined ___ primate behavior.","非人类的"],"languid":["慵懒无力的","The cat made a ___ movement in the sun.","慵懒的"],"doorknob":["门把手","He turned the ___ and entered.","门把手"],"sugary":["含糖多的","She avoided ___ drinks before bed.","多糖的"],"sparingly":["少量地；节制地","Use salt ___ when cooking the soup.","少量地"],"exorbitant":["过高的；离谱的","The hotel charged an ___ price for breakfast.","过高的"],"bodice":["连衣裙上身部分","The dress had an embroidered ___.","连衣裙上身"],"intentness":["专注；全神贯注","Her ___ was clear from her expression.","专注"],"stepmother":["继母","His ___ helped him prepare for school.","继母"],"endoscopic":["内窥镜的","The doctor recommended an ___ examination.","内窥镜的"],"silken":["丝质般柔滑的","She wore a ___ scarf.","丝滑的"],"candidly":["坦率地","He spoke ___ about the project's failures.","坦率地"],"breakneck":["极快的；危险高速的","The team worked at a ___ pace.","极快的"],"extricate":["使摆脱困境","The rescuers tried to ___ the trapped climber.","使摆脱"],"blissful":["幸福快乐的","They enjoyed a ___ afternoon by the sea.","幸福的"],"sickle":["镰刀","The farmer used a ___ to cut the grass.","镰刀"],"namesake":["同名者","The baby was named after her famous ___.","同名者"],"earthen":["泥土制的；陶土的","Water was stored in an ___ pot.","陶土的"],"mythological":["神话中的","The novel features a ___ creature.","神话中的"],"crass":["粗俗无礼的","His ___ comment offended the audience.","粗俗的"],"nucleolus":["核仁","The biologist identified a ___ inside the cell nucleus.","核仁"],"foundling":["弃婴","The novel follows a ___ raised by strangers.","弃婴"],"obtainable":["可获得的","The original report is still ___ online.","可获得的"],"gleefully":["高兴地","The children ___ opened their presents.","高兴地"],"scullery":["洗涤间；旧式厨房杂务间","The servants washed dishes in the ___.","洗涤间"],"headdress":["头饰","The dancer wore a colorful ___.","头饰"],"affable":["和蔼可亲的","The ___ host welcomed everyone warmly.","和蔼的"],"undated":["未注明日期的","The archive contained an ___ letter.","无日期的"],"latterly":["近来；最近","She has ___ focused on climate research.","最近"],"rueful":["懊悔的；悔恨的","He gave a ___ smile after the mistake.","懊悔的"],"retinue":["随从人员","The prince arrived with a large ___.","随从"],"clumsily":["笨拙地","He ___ dropped the glass.","笨拙地"],"invincible":["不可战胜的","The team seemed ___ after ten straight wins.","不可战胜的"],"manifestly":["显然地","The proposal was ___ unfair to small firms.","显然地"],"gusto":["热情；兴致勃勃","The children sang with ___.","热情"],"acquiesce":["默许；勉强同意","The committee eventually agreed to ___ to the request.","默许"],"ably":["干练地；能干地","The deputy ___ managed the emergency.","能干地"],"disbelieve":["不相信","It was difficult to ___ the eyewitness account.","不相信"],"unseemly":["不得体的","The manager apologized for the ___ behavior.","不得体的"],"penniless":["身无分文的","He arrived in the city almost ___.","身无分文的"],"hilt":["剑柄","The knight grasped the sword by its ___.","剑柄"],"indignantly":["愤慨地","She ___ rejected the accusation.","愤慨地"],"eternally":["永远地","The legend says the stars shine ___.","永远地"],"muslin":["细棉布","She made curtains from light ___.","细棉布"],"trite":["陈腐的；老套的","The reviewer criticized the film's ___ dialogue.","老套的"],"untrained":["未经训练的","An ___ worker should not operate the machine.","未经训练的"],"skylight":["天窗","Sunlight entered through the ___.","天窗"],"cologne":["古龙水","He applied a little ___ before leaving.","古龙水"],"effortful":["费力的","The steep climb made each step ___.","费力的"],"amputate":["截肢；切除肢体","Surgeons had to ___ the severely injured limb.","截肢"],"merciless":["无情的","The critic delivered a ___ review.","无情的"],"husbandry":["畜牧业；农事管理","The course covered modern animal ___.","畜牧管理"],"derisive":["嘲弄的","The speaker faced ___ laughter from the audience.","嘲弄的"],"unending":["无尽的","The travelers crossed a seemingly ___ plain.","无尽的"],"wily":["狡猾的","The ___ fox escaped the trap.","狡猾的"],"odious":["令人憎恶的","The council condemned the ___ act.","可憎的"],"oft":["常常（古体）","The poem uses ___ to mean often.","常常"],"craftsmanship":["工艺技艺","The handmade cabinet showed excellent ___.","手艺"],"conclusiveness":["结论性；确定性","The committee questioned the ___ of the evidence.","确定性"],"entreat":["恳求","The children continued to ___ their parents for help.","恳求"],"despicable":["卑鄙的","The judge called the fraud a ___ act.","卑鄙的"],"leathery":["皮革般的；坚韧的","The old tree had rough, ___ bark.","皮革般的"],"alacrity":["敏捷；欣然","She accepted the assignment with ___.","欣然"],"cowardice":["懦弱；胆怯","He regretted his ___ during the crisis.","懦弱"]}''')
index=json.loads((batchroot/"index.json").read_text())
by_lemma={}
for b in index["batches"]:
    f=batchroot/("batch%03d"%b["batch"])/"bilingual_ku_editorial_candidates.jsonl"
    for line in f.open(encoding="utf8"):
        r=json.loads(line)
        if r["lemma"] in entries and r["editing_state"]=="EDITORIAL_SINGLE_GLOSS_CANDIDATE":
            by_lemma.setdefault(r["lemma"],[]).append(r)
with gzip.open("data/core20k-runtime.json.gz","rt",encoding="utf8") as f:
    words=json.load(f)["headwords"]
out=[];skipped={}
for lemma,(zh,prompt,cue) in entries.items():
    candidates=by_lemma.get(lemma,[])
    if len(candidates)!=1:
        skipped[lemma]="NOT_EXACTLY_ONE_LOW_RISK_SOURCE";continue
    r=candidates[0];rank=r["rank"]
    assert words[rank-1][1].casefold()==lemma and prompt.count("___")==1
    response=lemma.title() if lemma in {"october","january","june","february","november","december","september","april","monday"} else lemma
    out.append({"draft_sense_id":f"staging:v21:bilingual:{rank}:{r['oewn_sense_id']}",
      "headword_id":f"core20k:rank:{rank}","rank":rank,"lemma":lemma,
      "oewn_sense_id":r["oewn_sense_id"],"definition_en_source":r["definition_en"],
      "gloss_zh_editorial":zh,"ecdict_wordlevel_reference":r["translation_zh_wordlevel_source"],
      "draft_ku_id":f"staging:v21:missing:{rank}:editorial11",
      "ku_type":"sense","render_kind":"guided_cloze",
      "question_instruction_zh":f"根据“{cue}”补全英文句子。",
      "prompt":prompt,"context_en":prompt.replace("___",response),
      "correct_answer":response,"acceptable_answers":[response],
      "source_attribution":"OEWN2025 exact Sense + ECDICT word-level evidence + original AI editorial context",
      "review_status":"AI_BILINGUAL_EDITORIAL_NEEDS_INDEPENDENT_SEMANTIC_AND_ASSESSMENT_QA",
      "independent_semantic_certified":False,"release_eligible":False,"production_ready":False})
assert len(out)>0 and len({x["draft_ku_id"] for x in out})==len(out)
dest=root/"bilingual_sense_ku_curated_batch11.jsonl"
dest.write_text("".join(json.dumps(r,ensure_ascii=False)+"\n" for r in out),encoding="utf8")
print("BILINGUAL_CURATED_BATCH11_PASS",json.dumps({"authored":len(entries),"new_bilingual_editorial_senses":len(out),"new_original_context_kus":len(out),"skipped":skipped,"independent_certified":0,"production_ready":0},ensure_ascii=False))
